import React from 'react';
import styled from 'styled-components';

const EducationContainer = styled.div`
  padding: 20px;
  max-width: 800px;
  margin: 20 auto;
  text-align: center;
`;

const Title = styled.h1`
  font-size: 36px;
  margin-bottom: 20px;
`;

const EducationSection = styled.div`
  margin-bottom: 30px;
`;

const Degree = styled.h2`
  font-size: 24px;
  margin-bottom: 10px;
`;

const Institution = styled.h3`
  font-size: 20px;
  margin-bottom: 5px;
`;

const Duration = styled.p`
  font-size: 16px;
  color: #666;
  margin-bottom: 10px;
`;

const Education = () => {
  return (
    <EducationContainer>
      <Title>EDUCATION</Title>

      <EducationSection>
        <Degree>Bachelor’s of Art</Degree>
        <Institution>Karakorum International University, Gilgit</Institution>
        <Duration>2017 - 2020</Duration>
      </EducationSection>

      <EducationSection>
        <Degree>Faculty of Arts</Degree>
        <Institution>Government Degree College Cupis, Chizer</Institution>
        <Duration>2015 - 2017</Duration>
      </EducationSection>
    </EducationContainer>
  );
};

export default Education;
